```java
import com.alibaba.csp.sentinel.Entry;
import com.alibaba.csp.sentinel.EntryType;
import com.alibaba.csp.sentinel.slots.block.flow.FlowRule;
import com.alibaba.csp.sentinel.slots.block.flow.FlowRuleManager;

public class SentinelExample {
    public static void main(String[] args) throws InterruptedException {
        // Load rules from file
        FlowRule rule = new FlowRule("yourServiceName");
        rule.setGrade(RuleConstant.FLOW_GRADE_QPS); // Set the grade to QPS (requests per second)
        rule.setCount(10); // Limit to 10 requests per second
        rule.setResource("yourResource"); // Specify the resource to limit
        rule.setLimitApp("default"); // Default application name
        rule.setEnabled(true); // Enable the rule

        // Add the rule to the rule manager
        FlowRuleManager.loadRules(Collections.singletonList(rule));

        // Entry point for the service
        Entry entry = Entry.entry("yourServiceName", EntryType.SERVICE);
        if (entry!= null) {
            System.out.println("Service entry point is available.");
            // Your service logic here
        } else {
            System.out.println("Service entry point is unavailable.");
        }

        Thread.sleep(60000); // Sleep for 60 seconds to allow the flow control to take effect
    }
}
```

